"""`docs/reference/**`: the eighth generated output, the one written for humans. **D990.**

11-repo-layout.md section 1.8 names the directory and its contents -- *"`reference/` GENERATED:
the CLI verb tree, the SDK stubs, `codes.toml` rendered"* -- and says which gate holds it:
*"`docs/reference/**` is generated by `ow surface emit --docs` and byte-diff checked by the
`[[job_assertion]]` `gates.reference_docs`, **not** by G25 -- G25's set is the seven agent-facing
artefacts the charter fixes, and `docs/reference/` is an eighth output for humans."*

So this module renders and `gen.emit` writes, exactly as the seven do, and the three documents are
byte-diff gated under their own assertion rather than inside G25's count.

## Rulings

1. **Three documents, one per source the section names.** `cli.md` is the verb tree, `sdk.md` the
   Action surface a caller programs against, and `codes.md` `codes.toml` rendered. One file each,
   because the section's phrase is a list of three and a reader looking for an error code should
   not have to scroll a combined page.
2. **Every byte comes from a register.** `cli_tree.commands()` for the verb tree -- the same
   function the generated argparse tree is built from, so the document cannot describe a CLI the
   CLI does not have -- `registry.ACTIONS` for the SDK surface, and `codes.toml` for the codes.
   Nothing here is prose about the code; the prose is in the header each document carries.
3. **Deterministic, and sorted at every level.** No clock, no environment, no iteration over an
   unsorted set (10:224). A generated document that changed between two runs of one commit would
   make its own byte-diff gate meaningless.
4. **A human reads these, so the shape is a table and not a dump.** Each document leads with what
   it is generated from and the command that rewrites it, which is 11:486's rule for every
   generated file: the header tells its reader not to edit it and names the command.
5. **`docs/reference/` is the directory and nothing else lives there.** The assertion byte-diffs
   the tree, so a stray file is a finding -- the `_committed_tree` shape `gen.emit` already uses
   for the one `TREE` artefact.

Specified in 11-repo-layout.md sections 1.8 and 6.4 (`gates.reference_docs`).
"""

from __future__ import annotations

import dataclasses
import tomllib
from pathlib import Path
from typing import TYPE_CHECKING, Any, Final

from omniweave.gen import cli_tree
from omniweave.surface import registry

if TYPE_CHECKING:
    from collections.abc import Mapping

__all__ = ["DIRECTORY", "DOCUMENTS", "cli_md", "codes_md", "render_docs", "sdk_md"]

REPO_ROOT: Final = Path(__file__).resolve().parents[5]
DIRECTORY: Final = "docs/reference"
CODES: Final = "codes.toml"
_EDIT: Final = (
    "**GENERATED** by `ow surface emit --docs`. Do not edit: the `gates.reference_docs` job\n"
    "assertion byte-diffs this directory, so a hand edit fails CI and the next emit overwrites it."
)


def _header(title: str, source: str) -> list[str]:
    """Ruling 4: what it is, what it is generated from, and the command that rewrites it."""
    return [f"# {title}", "", _EDIT, "", f"Generated from {source}.", ""]


def cli_md() -> bytes:
    """The verb tree, from the same `commands()` the argparse tree is generated from (ruling 2)."""
    out = _header(
        "`ow` command reference",
        "`omniweave.gen.cli_tree.commands()`, which is also what builds `ow`'s argparse tree",
    )
    out += [
        "Every command below is one Action of `omniweave.surface.registry.ACTIONS`. A flag's",
        "`kind` is the type its value parses as; `switch` takes no value.",
        "",
    ]
    for words, actions, summary, flags in sorted(cli_tree.commands()):
        out += [f"## `ow {' '.join(words)}`", "", summary, ""]
        out.append(f"Action: `{'`, `'.join(actions)}`")
        out.append("")
        if not flags:
            out += ["Takes no argument.", ""]
            continue
        out += ["| argument | kind | detail |", "|---|---|---|"]
        for flag in flags:
            spelling = ", ".join(f"`{one}`" for one in flag.spelling)
            out.append(f"| {spelling} | {flag.kind} | {_detail(flag)} |")
        out.append("")
    return "\n".join(out).encode("utf-8")


def _detail(flag: Any) -> str:
    """One flag's metavar, choices, default and help, in that order, as one cell."""
    parts = []
    if flag.metavar:
        parts.append(f"`{flag.metavar}`")
    if flag.nargs:
        parts.append(f"nargs `{flag.nargs}`")
    if flag.choices:
        parts.append("one of " + ", ".join(f"`{one}`" for one in flag.choices))
    if flag.default is not None:
        parts.append(f"default `{flag.default}`")
    if flag.help:
        parts.append(flag.help)
    return _cell("; ".join(parts)) or "--"


def _cell(text: str) -> str:
    """One table cell's text: a pipe escaped, because a union type is full of them."""
    return text.replace("|", r"\|")


def _fields(model: type | None) -> list[tuple[str, str, str]]:
    """One input model's fields as `(name, type, default)`, in declaration order."""
    if model is None or not dataclasses.is_dataclass(model):
        return []
    out = []
    for field in dataclasses.fields(model):
        default = "" if field.default is dataclasses.MISSING else repr(field.default)
        if field.default_factory is not dataclasses.MISSING:  # type: ignore[misc]
            default = "(factory)"
        out.append((field.name, str(field.type), default))
    return out


def sdk_md() -> bytes:
    """The Action surface: what a caller programs against, from the registry itself (ruling 2)."""
    out = _header(
        "SDK and Action reference",
        "`omniweave.surface.registry.ACTIONS`, the one declaration every surface is generated from",
    )
    out += [
        "One section per Action. `mcp` is the tool name an MCP client sees, `--` for an Action",
        "that is human-only; `cli` is the command words. The four booleans are the Action's own",
        "declaration and are what the MCP annotations and the CLI's refusals are built from.",
        "",
    ]
    for name in sorted(registry.ACTIONS):
        spec = registry.ACTIONS[name]
        out += [f"## `{name}`", "", spec.summary, ""]
        out += [
            "| property | value |",
            "|---|---|",
            f"| cli | {'`ow ' + ' '.join(spec.cli) + '`' if spec.cli else '--'} |",
            f"| mcp | {'`' + spec.mcp_name + '`' if spec.mcp_name else '--'} |",
            f"| listed in | {', '.join(sorted(spec.listed_in)) or '--'} |",
            f"| read_only | {spec.read_only} |",
            f"| idempotent | {spec.idempotent} |",
            f"| open_world | {spec.open_world} |",
            f"| destructive | {spec.destructive} |",
            f"| cost class | `{spec.cost_class.value}` |",
            f"| input | `{spec.inp.__name__ if spec.inp else '--'}` |",
            f"| output | `{spec.out.__name__ if spec.out else '--'}` |",
            "",
        ]
        fields = _fields(spec.inp)
        if fields:
            out += ["| input field | type | default |", "|---|---|---|"]
            #  A union type carries a pipe (`str | None`), which would end the cell: a markdown
            #  table cannot hold an unescaped one, and `AddIn.source` is exactly that shape.
            out += [
                f"| `{one}` | `{_cell(kind)}` | {_cell(default) or '--'} |"
                for one, kind, default in fields
            ]
            out.append("")
        if spec.decision:
            out += [f"When to reach for it: {spec.decision}.", ""]
    return "\n".join(out).encode("utf-8")


def codes_md() -> bytes:
    """`codes.toml` rendered: the areas, the exit codes, and every row (ruling 1)."""
    raw = tomllib.loads((REPO_ROOT / CODES).read_text(encoding="utf-8"))
    out = _header(
        "`OW-` error code reference",
        "`codes.toml`, the register G13 holds append-only against the previous tag",
    )
    areas = raw.get("area", {})
    if isinstance(areas, dict) and areas:
        out += ["## Areas", "", "| area | what it covers |", "|---|---|"]
        out += [f"| `{key}` | {areas[key]} |" for key in sorted(areas)]
        out.append("")
    exits = raw.get("exit", {})
    if isinstance(exits, dict) and exits:
        out += ["## Exit codes", "", "| code | meaning |", "|---|---|"]
        out += [f"| `{key}` | {exits[key]} |" for key in sorted(exits, key=str)]
        out.append("")
    rows = [row for row in raw.get("code", []) if isinstance(row, dict)]
    out += [f"## Codes ({len(rows)})", ""]
    for row in sorted(rows, key=lambda one: str(one.get("numeric", ""))):
        out += [f"### `{row.get('numeric', '?')}` -- `{row.get('symbol', '?')}`", ""]
        out += [str(row.get("meaning", "")).strip(), ""]
        if row.get("fix"):
            out += ["Clears with:", "", f"```console\n$ {str(row['fix']).strip()}\n```", ""]
        if row.get("raised_by"):
            out += [f"Raised by `{row['raised_by']}`.", ""]
    return "\n".join(out).encode("utf-8")


DOCUMENTS: Final[Mapping[str, Any]] = {
    "cli.md": cli_md,
    "codes.md": codes_md,
    "sdk.md": sdk_md,
}
"""Ruling 1: the three documents, keyed by their path under `docs/reference/`."""


def render_docs() -> dict[str, bytes]:
    """Every reference document, sorted (ruling 3). Pure: no path written, no clock read."""
    return {name: render() for name, render in sorted(DOCUMENTS.items())}
